import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";

export default function PostAttributesPage() {
  const { category } = useParams();

  // Form State
  const [formData, setFormData] = useState({
    title: "",
    description: "",
    price: "",
    category: category,
    location: "",
  });

  // Update category when URL parameter changes
  useEffect(() => {
    setFormData((prevData) => ({ ...prevData, category: category }));
  }, [category]);

  // Handle input changes
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  // Form submission
  const handleSubmit = (e) => {
    e.preventDefault();
    alert("Form submitted successfully!");
    console.log(formData); // For debugging
  };

  return (
    <div className="container mx-auto px-4 py-6">
      {/* Header Section */}
      <div className="mb-6 text-center">
        <h1 className="text-3xl font-semibold text-gray-800">Post Your Ad</h1>
        <p className="text-gray-600 mt-2">Fill in the details to post your ad.</p>
      </div>

      {/* Form Section */}
      <form
        onSubmit={handleSubmit}
        className="bg-white shadow-md rounded-md p-6 space-y-4 max-w-2xl mx-auto"
      >
        {/* Title */}
        <div>
          <label htmlFor="title" className="block text-gray-700 font-medium">
            Title <span className="text-red-500">*</span>
          </label>
          <input
            type="text"
            name="title"
            id="title"
            value={formData.title}
            onChange={handleInputChange}
            required
            placeholder="Enter ad title"
            className="mt-1 block w-full p-3 border rounded-md shadow-sm focus:ring-red-500 focus:border-red-500"
          />
        </div>

        {/* Description */}
        <div>
          <label htmlFor="description" className="block text-gray-700 font-medium">
            Description <span className="text-red-500">*</span>
          </label>
          <textarea
            name="description"
            id="description"
            value={formData.description}
            onChange={handleInputChange}
            required
            placeholder="Enter ad description"
            className="mt-1 block w-full p-3 border rounded-md shadow-sm focus:ring-red-500 focus:border-red-500"
            rows={4}
          ></textarea>
        </div>

        {/* Price */}
        <div>
          <label htmlFor="price" className="block text-gray-700 font-medium">
            Price (in EGP) <span className="text-red-500">*</span>
          </label>
          <input
            type="number"
            name="price"
            id="price"
            value={formData.price}
            onChange={handleInputChange}
            required
            placeholder="Enter price"
            className="mt-1 block w-full p-3 border rounded-md shadow-sm focus:ring-red-500 focus:border-red-500"
          />
        </div>

        {/* Category */}
        <div>
          <label htmlFor="category" className="block text-gray-700 font-medium">
            Category <span className="text-red-500">*</span>
          </label>
          <input
            type="text"
            id="category"
            name="category"
            value={formData.category}
            readOnly
            className="mt-1 block w-full border-gray-300 rounded-md shadow-sm bg-gray-100 cursor-not-allowed"
          />
        </div>

        {/* Location */}
        <div>
          <label htmlFor="location" className="block text-gray-700 font-medium">
            Location
          </label>
          <input
            type="text"
            name="location"
            id="location"
            value={formData.location}
            onChange={handleInputChange}
            placeholder="Enter location"
            className="mt-1 block w-full p-3 border rounded-md shadow-sm focus:ring-red-500 focus:border-red-500"
          />
        </div>

        {/* Submit Button */}
        <button
          type="submit"
          className="w-full bg-red-500 text-white py-3 rounded-md hover:bg-red-700 transition"
        >
          Submit Ad
        </button>
      </form>

      {/* Preview Section */}
      <div className="mt-8 max-w-2xl mx-auto">
        <h2 className="text-xl font-semibold text-gray-800">Preview</h2>
        <div className="bg-gray-100 p-4 rounded-md mt-4 space-y-3">
          <p><strong>Title:</strong> {formData.title || "Not provided"}</p>
          <p><strong>Description:</strong> {formData.description || "Not provided"}</p>
          <p><strong>Price:</strong> {formData.price ? `${formData.price} EGP` : "Not provided"}</p>
          <p><strong>Category:</strong> {formData.category}</p>
          <p><strong>Location:</strong> {formData.location || "Not provided"}</p>
        </div>
      </div>
    </div>
  );
}
